324	export function countCompleteAirworthinessChecks(
325	  checks: Record<string, AirworthinessStatus> | undefined,
326	): number {
327	  if (!checks) return 0;
328	  let count = 0;
329	  for (const value of Object.values(checks)) {
330	    if (value === 'confirmed' || value === 'na' || value === true) count += 1;
331	  }
332	  return count;
333	}
