335	export function listCompleteAirworthinessIds(
336	  checks: Record<string, AirworthinessStatus> | undefined,
337	): string[] {
338	  if (!checks) return [];
339	  const ids: string[] = [];
340	  for (const [key, value] of Object.entries(checks)) {
341	    if (value === 'confirmed' || value === 'na' || value === true) {
342	      ids.push(key);
343	    }
344	  }
345	  return ids;
346	}
