348	export function validateDispatchAssessmentPayload(
349	  raw: unknown,
350	): DispatchPayloadValidationResult {
351	  const errors: string[] = [];
352	  const source = unwrapScenarioInputs(raw);
353	  if (!isRecord(source)) {
354	    return { ok: false, error: 'scenarioInputs must be an object' };
355	  }
356	  if (Object.keys(source).length === 0) {
357	    return { ok: false, error: 'scenarioInputs cannot be empty' };
358	  }
359	
360	  for (const key of Object.keys(source)) {
361	    if (!ALLOWED_TOP_LEVEL_KEYS.has(key)) {
362	      errors.push(`unsupported field: ${key}`);
363	    }
364	  }
365	
366	  const payload: DispatchAssessmentPayload = {
367	    profileName: readString(source, 'profileName', errors, {
368	      min: 2,
369	      max: 120,
370	    }),
371	    profileType: readProfileType(source, errors),
372	    totalHours: readNumber(source, 'totalHours', errors, 0, 50000),
373	    recentHours30: readNumber(source, 'recentHours30', errors, 0, 500),
374	    aircraft: readString(source, 'aircraft', errors, { min: 1, max: 80 }),
375	    lesson: readString(source, 'lesson', errors, { min: 1, max: 160 }),
376	    student: readString(source, 'student', errors, { min: 1, max: 120 }),
377	    instructor: readString(source, 'instructor', errors, { min: 1, max: 120 }),
378	    scheduledDate: readDate(source, 'scheduledDate', errors),
379	    scheduledTime: readTime(source, 'scheduledTime', errors),
380	    duration: readString(source, 'duration', errors, { min: 1, max: 40 }),
381	    route: readString(source, 'route', errors, { min: 1, max: 160 }),
382	    departure: readAirport(source, 'departure', errors),
383	    destination: readAirport(source, 'destination', errors),
384	    disclaimerAccepted: readBoolean(source, 'disclaimerAccepted', errors),
385	    moduleObjectives: readBooleanRecord(source, 'moduleObjectives', errors),
386	    airworthiness: readAirworthiness(source, errors),
387	    performance: readPerformance(source, errors),
388	    weightBalance: readWeightBalance(source, errors),
389	    riskFactors: readRiskFactors(source, errors),
390	  };
391	
392	  if (typeof source.sourceProfileId === 'string' && source.sourceProfileId) {
393	    if (!isUuidLike(source.sourceProfileId)) {
394	      errors.push('sourceProfileId must be a UUID');
395	    } else {
396	      payload.sourceProfileId = source.sourceProfileId;
397	    }
398	  }
399	  if ('imsafeChecks' in source) {
400	    payload.imsafeChecks = readImsafeChecks(source, errors);
401	  }
402	  if ('imsafeDetails' in source) {
403	    payload.imsafeDetails = readImsafeDetails(source, errors);
404	  }
405	  if ('safetyChecks' in source) {
406	    payload.safetyChecks = readSafetyChecks(source, errors);
407	  }
408	
409	  const moduleComplete = Object.values(payload.moduleObjectives).every(Boolean);
410	  if (Object.keys(payload.moduleObjectives).length === 0) {
411	    errors.push('moduleObjectives must contain at least one objective');
412	  }
413	  if (!moduleComplete) {
414	    errors.push('moduleObjectives must all be reviewed before simulation');
415	  }
416	
417	  return errors.length > 0
418	    ? { ok: false, error: errors.join('; ') }
419	    : { ok: true, data: payload };
420	}
