422	export function assertDispatchAssessmentPayload(
423	  raw: unknown,
424	): DispatchAssessmentPayload {
425	  const result = validateDispatchAssessmentPayload(raw);
426	  if (!result.ok) throw new Error(result.error);
427	  return result.data;
428	}
