430	export function assessDispatchRisk(
431	  payload: DispatchAssessmentPayload,
432	): DispatchAssessment {
433	  const flags: string[] = [];
434	  const blocks: string[] = [];
435	  const mitigations = new Set<string>();
436	
437	  const pilotContributions: string[] = [];
438	  const imsafeChecks = normalizeImsafeChecks(payload);
439	  const imsafeConcerns = DISPATCH_IMSAFE_ITEM_IDS.filter(
440	    (id) => imsafeChecks[id] === 'no',
441	  );
442	  const granularImsafeScore = payload.imsafeDetails
443	    ? scoreDispatchImsafe(payload.imsafeDetails)
444	    : null;
445	  let pilotScore = granularImsafeScore
446	    ? granularImsafeScore.score
447	    : imsafeConcerns.length * 4;
448	  if (granularImsafeScore) {
449	    pilotContributions.push(
450	      ...granularImsafeScore.contributions.map(
451	        (item) => `${item.factor}: ${item.reason}`,
452	      ),
453	    );
454	    if (granularImsafeScore.contributions.length > 0) {
455	      flags.push('Granular IMSAFE risk elevated');
456	      mitigations.add('Review detailed IMSAFE factors before release');
457	    }
458	    for (const hardStop of granularImsafeScore.hardStops) {
459	      blocks.push(`IMSAFE hard stop: ${hardStop}`);
460	    }
461	  }
462	  if (!granularImsafeScore && payload.totalHours < 75) {
463	    pilotScore += 8;
464	    flags.push('Low total time');
465	    pilotContributions.push('Low total time');
466	  }
467	  if (payload.recentHours30 < 3) {
468	    pilotScore += 10;
469	    flags.push('Low recent experience');
470	    pilotContributions.push('Low recent experience');
471	  }
472	  if (payload.riskFactors.crew) {
473	    pilotScore += 12;
474	    flags.push('Crew factors elevated');
475	    pilotContributions.push('Crew factors elevated');
476	    mitigations.add('Review crew readiness before release');
477	  }
478	  // External pressures are a crew factor (PAVE: Pilot), not a standalone
479	  // External-category input — get-there-itis and outside pressure act on the
480	  // pilot's decision-making, so the contribution is scored under Pilot.
481	  if (payload.riskFactors.externalPressures) {
482	    pilotScore += 12;
483	    flags.push('External pressures present');
484	    pilotContributions.push('External pressures present');
485	    mitigations.add('Document external pressure mitigation');
486	  }
487	  if (!granularImsafeScore) {
488	    pilotContributions.push(
489	      ...imsafeConcerns.map((id) => `IM SAFE concern: ${id}`),
490	    );
491	  }
492	
493	  const missingAirworthiness = Object.entries(payload.airworthiness)
494	    .filter(([, value]) => !(value === 'confirmed' || value === 'na' || value))
495	    .map(([key]) => key);
496	  let aircraftScore = 0;
497	  const aircraftContributions: string[] = [];
498	  if (missingAirworthiness.length > 0) {
499	    aircraftScore += Math.min(24, missingAirworthiness.length * 6);
500	    flags.push('Airworthiness action required');
501	    blocks.push('Airworthiness checklist incomplete');
502	    aircraftContributions.push(
503	      ...missingAirworthiness.map((id) => `Missing: ${id}`),
504	    );
505	    mitigations.add('Resolve missing airworthiness items before dispatch');
506	  }
507	
508	  const performance = scorePerformance(payload);
509	  flags.push(...performance.flags);
510	  for (const item of performance.mitigations) mitigations.add(item);
511	
512	  const wb = scoreWeightBalance(payload);
513	  flags.push(...wb.flags);
514	  for (const item of wb.mitigations) mitigations.add(item);
515	
516	  const safetyChecks = normalizeSafetyChecks(payload);
517	  const missingSafety = DISPATCH_SAFETY_ITEM_IDS.filter(
518	    (id) => !safetyChecks[id],
519	  );
520	  let externalScore = 0;
521	  const externalContributions: string[] = [];
522	  if (missingSafety.length > 0) {
523	    externalScore += Math.min(18, missingSafety.length * 4);
524	    flags.push('Safety planning items incomplete');
525	    externalContributions.push(
526	      ...missingSafety.map((id) => `Missing safety item: ${id}`),
527	    );
528	    mitigations.add('Complete safety planning items before release');
529	  }
530	  if (payload.riskFactors.taskLoading) {
531	    externalScore += 10;
532	    flags.push('Task loading elevated');
533	    externalContributions.push('Task loading elevated');
534	    mitigations.add('Brief task saturation triggers and abort criteria');
535	  }
536	  if (payload.riskFactors.additiveConditions) {
537	    externalScore += 12;
538	    flags.push('Additive conditions present');
539	    externalContributions.push('Additive conditions present');
540	    mitigations.add('Confirm additive condition mitigations');
541	  }
542	  if (!payload.disclaimerAccepted) {
543	    externalScore += 20;
544	    blocks.push('PIC responsibility acknowledgement incomplete');
545	    externalContributions.push('PIC acknowledgement incomplete');
546	  }
547	  if (!Object.values(payload.moduleObjectives).every(Boolean)) {
548	    externalScore += 20;
549	    blocks.push('Training module review incomplete');
550	    externalContributions.push('Module review incomplete');
551	  }
552	
553	  const factors: Record<string, DispatchFactorScore> = {
554	    Pilot: factor('Pilot', pilotScore, pilotContributions),
555	    Aircraft: factor('Aircraft', aircraftScore, aircraftContributions),
556	    Environment: factor(
557	      'Environment',
558	      performance.score,
559	      performance.contributions,
560	    ),
561	    'Weight & Balance': factor('Weight & Balance', wb.score, wb.contributions),
562	    External: factor('External', externalScore, externalContributions),
563	  };
564	
565	  const riskScore = clampScore(
566	    Object.values(factors).reduce((sum, item) => sum + item.rawScore, 0),
567	  );
568	  const riskLevel = riskLevelForScore(riskScore);
569	  const riskLevelUpper = riskLevel.toUpperCase() as RiskLevelUpper;
570	  if (mitigations.size === 0) mitigations.add('Standard pre-flight briefing');
571	
572	  return {
573	    riskScore,
574	    riskLevel,
575	    riskLevelUpper,
576	    factors,
577	    flags: Array.from(new Set(flags)),
578	    blocks: Array.from(new Set(blocks)),
579	    mitigations: Array.from(mitigations),
580	    triggeredRuleIds: [],
581	    reasoning: [
582	      `Shared dispatch assessment scored ${riskScore}/100 (${riskLevelUpper}).`,
583	      'Inputs included flight, acknowledgement, module, airworthiness, performance, Weight & Balance, Risk Factors, route, and weather/environment fields.',
584	    ].join(' '),
585	    intervention: Array.from(mitigations).join('; '),
586	    pave: [
587	      {
588	        label: 'Pilot',
589	        score: factors.Pilot.rawScore,
590	        max: DISPATCH_FACTOR_MAX_SCORES.Pilot,
591	        items: pilotContributions,
592	      },
593	      {
594	        label: 'Aircraft',
595	        score: factors.Aircraft.rawScore,
596	        max: DISPATCH_FACTOR_MAX_SCORES.Aircraft,
597	        items: aircraftContributions,
598	      },
599	      {
600	        label: 'Environment',
601	        score: factors.Environment.rawScore,
602	        max: DISPATCH_FACTOR_MAX_SCORES.Environment,
603	        items: performance.contributions,
604	      },
605	      {
606	        label: 'External',
607	        score: factors.External.rawScore,
608	        max: DISPATCH_FACTOR_MAX_SCORES.External,
609	        items: externalContributions,
610	      },
611	    ],
612	  };
613	}
614	
615	function scorePerformance(payload: DispatchAssessmentPayload) {
616	  const contributions: string[] = [];
617	  const flags: string[] = [];
618	  const mitigations: string[] = [];
619	  let score = 5;
620	
621	  const densityAltitude = parseNumber(payload.performance.densityAltitude);
622	  if (densityAltitude > 3000) {
623	    score += 10;
624	    flags.push('High density altitude');
625	    contributions.push(`Density altitude ${densityAltitude} ft`);
626	    mitigations.push('Verify performance margins at observed density altitude');
627	  } else {
628	    contributions.push(`Density altitude ${densityAltitude || 0} ft`);
629	  }
630	
631	  const safetyFactor = parseNumber(payload.performance.safetyFactor);
632	  if (safetyFactor > 0 && safetyFactor < 1.2) {
633	    score += 12;
634	    flags.push('Runway margin below target');
635	    contributions.push(`Safety factor ${safetyFactor}`);
636	    mitigations.push('Increase runway margin or reduce load');
637	  }
638	
639	  const runwayCondition = payload.performance.runwayCondition.toLowerCase();
640	  if (/(wet|contam|snow|ice|slush|poor|rcc\s?[0-4])/.test(runwayCondition)) {
641	    score += 8;
642	    flags.push('Runway condition elevated');
643	    contributions.push(
644	      `Runway condition ${payload.performance.runwayCondition}`,
645	    );
646	    mitigations.push('Review runway contamination performance correction');
647	  }
648	
649	  const windSpeed = parseWindSpeed(payload.performance.wind);
650	  if (windSpeed >= 18) {
651	    score += 8;
652	    flags.push('Wind elevated');
653	    contributions.push(`Wind ${payload.performance.wind}`);
654	    mitigations.push('Confirm crosswind and gust limits');
655	  }
656	
657	  const routeText = `${payload.route} ${payload.departure} ${payload.destination}`;
658	  if (
659	    payload.departure.toUpperCase() !== payload.destination.toUpperCase() ||
660	    /[-→>]/.test(payload.route)
661	  ) {
662	    score += 3;
