669	function scoreWeightBalance(payload: DispatchAssessmentPayload) {
670	  const contributions: string[] = [];
671	  const flags: string[] = [];
672	  const mitigations: string[] = [];
673	  let score = 0;
674	  const takeoffWeight = parseNumber(payload.weightBalance.takeoffWeight);
675	  const landingWeight = parseNumber(payload.weightBalance.landingWeight);
676	  const cg = parseNumber(payload.weightBalance.cg);
