682	  if (takeoffWeight > 2300) {
683	    score += takeoffWeight > 2550 ? 24 : 10;
684	    flags.push(
685	      takeoffWeight > 2550
686	        ? 'Weight exceeds expected limit'
687	        : 'Approaching weight limit',
688	    );
689	    mitigations.push('Reduce load or verify aircraft-specific maximum gross');
690	  }
691	  if (landingWeight > 2400) {
692	    score += 8;
693	    flags.push('Landing weight elevated');
694	  }
695	  if (cg > 0 && (cg < 37 || cg > 45)) {
696	    score += cg < 35 || cg > 47 ? 24 : 10;
697	    flags.push('CG outside preferred range');
698	    mitigations.push('Adjust loading to restore CG margin');
699	  }
