110	export function isDispatchCurrencyReady(
111	  details: Pick<
112	    DispatchImsafeDetails,
113	    | 'totalFlightHours'
114	    | 'hoursInType'
115	    | 'hoursInType90'
116	    | 'daytimeLandingCurrent'
117	    | 'nighttimeLandingCurrent'
118	    | 'medicalValid'
119	    | 'ifrCurrent'
120	    | 'flightReviewCurrent'
121	  >,
122	): boolean {
123	  return (
124	    details.totalFlightHours > 0 &&
125	    details.hoursInType > 0 &&
126	    details.hoursInType90 > 0 &&
127	    details.daytimeLandingCurrent &&
128	    details.nighttimeLandingCurrent &&
129	    details.medicalValid &&
130	    details.ifrCurrent &&
131	    details.flightReviewCurrent
132	  );
