135	export function deriveDispatchImsafeChecks(
136	  details: DispatchImsafeDetails,
137	): Record<DispatchImsafeFactorId, 'yes' | 'no'> {
138	  return {
139	    illness:
140	      details.illness === 'moderate' || details.illness === 'significant'
141	        ? 'no'
142	        : 'yes',
143	    medication:
144	      details.medication === 'otc_sedating' ||
145	      details.medication === 'prescription'
146	        ? 'no'
147	        : 'yes',
148	    stress: details.stressLevel >= 8 ? 'no' : 'yes',
149	    alcohol:
150	      details.alcoholAbstinent || details.alcoholHours >= 8 ? 'yes' : 'no',
151	    fatigue:
152	      details.kssRating >= 8 ||
153	      details.hoursAwake > 20 ||
154	      details.sleepHours < 4
155	        ? 'no'
156	        : 'yes',
157	    eating: getDispatchEmotionScore(details) >= 7 ? 'no' : 'yes',
158	  };
159	}
