161	export function scoreDispatchImsafe(
162	  details: DispatchImsafeDetails,
163	): DispatchImsafeScore {
164	  const contributions: DispatchImsafeContribution[] = [];
165	
166	  switch (details.illness) {
167	    case 'minor':
168	      addContribution(contributions, {
169	        id: 'illness',
170	        factor: 'Illness',
171	        points: 1,
172	        severity: 'watch',
173	        reason: 'Minor illness or cold symptoms reported',
174	      });
175	      break;
176	    case 'moderate':
177	      addContribution(contributions, {
178	        id: 'illness',
179	        factor: 'Illness',
180	        points: 4,
181	        severity: 'caution',
182	        reason: 'Illness may impair performance',
183	      });
184	      break;
185	    case 'significant':
186	      addContribution(contributions, {
187	        id: 'illness',
188	        factor: 'Illness',
189	        points: 10,
190	        severity: 'critical',
191	        reason: 'Severe illness marked unable to fly',
192	        hardStop: true,
193	      });
194	      break;
195	  }
196	
197	  switch (details.medication) {
198	    case 'otc_non_sedating':
199	      addContribution(contributions, {
200	        id: 'medication',
201	        factor: 'Medication',
202	        points: 1,
203	        severity: 'watch',
204	        reason: 'OTC medication requires normal side-effect awareness',
205	      });
206	      break;
207	    case 'otc_sedating':
208	      addContribution(contributions, {
209	        id: 'medication',
210	        factor: 'Medication',
211	        points: 5,
212	        severity: 'caution',
213	        reason: 'Cautionary medication should be reviewed with an AME',
214	      });
215	      break;
216	    case 'prescription':
217	      addContribution(contributions, {
218	        id: 'medication',
219	        factor: 'Medication',
220	        points: 10,
221	        severity: 'critical',
222	        reason: 'Medication marked FAA prohibited',
223	        hardStop: true,
224	      });
225	      break;
226	  }
227	
228	  const stressLevel = clampNumber(details.stressLevel, 1, 10);
229	  if (stressLevel >= 8) {
230	    addContribution(contributions, {
231	      id: 'stress',
232	      factor: 'Stress',
233	      points: 6,
234	      severity: 'critical',
235	      reason: `Stress level ${stressLevel}/10`,
236	    });
237	  } else if (stressLevel >= 7) {
238	    addContribution(contributions, {
239	      id: 'stress',
240	      factor: 'Stress',
241	      points: 4,
242	      severity: 'caution',
243	      reason: `Stress level ${stressLevel}/10`,
244	    });
245	  } else if (stressLevel >= 4) {
246	    addContribution(contributions, {
247	      id: 'stress',
248	      factor: 'Stress',
249	      points: 2,
250	      severity: 'watch',
251	      reason: `Stress level ${stressLevel}/10`,
252	    });
253	  }
254	
255	  if (!details.alcoholAbstinent) {
256	    if (details.alcoholHours < 8) {
257	      addContribution(contributions, {
258	        id: 'alcohol',
259	        factor: 'Alcohol',
260	        points: 10,
261	        severity: 'critical',
262	        reason: `${details.alcoholHours} hours since alcohol consumption is below the 8-hour minimum`,
263	        hardStop: true,
264	      });
265	    } else if (details.alcoholHours < 24) {
266	      addContribution(contributions, {
267	        id: 'alcohol',
268	        factor: 'Alcohol',
269	        points: 2,
270	        severity: 'watch',
271	        reason: `${details.alcoholHours} hours since alcohol consumption`,
272	      });
273	    }
274	  }
275	
276	  if (details.kssRating >= 8) {
277	    addContribution(contributions, {
278	      id: 'fatigue',
279	      factor: 'Fatigue',
280	      points: 10,
281	      severity: 'critical',
282	      reason: `KSS ${details.kssRating} indicates significant sleepiness`,
283	      hardStop: true,
284	    });
285	  } else if (details.kssRating >= 7) {
286	    addContribution(contributions, {
287	      id: 'fatigue',
288	      factor: 'Fatigue',
289	      points: 6,
290	      severity: 'critical',
291	      reason: `KSS ${details.kssRating} indicates elevated fatigue`,
292	    });
293	  } else if (details.kssRating >= 6) {
294	    addContribution(contributions, {
295	      id: 'fatigue',
296	      factor: 'Fatigue',
297	      points: 4,
298	      severity: 'caution',
299	      reason: `KSS ${details.kssRating} indicates sleepiness`,
300	    });
301	  } else if (details.kssRating >= 4) {
302	    addContribution(contributions, {
303	      id: 'fatigue',
304	      factor: 'Fatigue',
305	      points: 2,
306	      severity: 'watch',
307	      reason: `KSS ${details.kssRating} is above fully alert range`,
308	    });
309	  }
310	
311	  if (details.hoursAwake > 20) {
312	    addContribution(contributions, {
313	      id: 'fatigue',
314	      factor: 'Fatigue',
315	      points: 6,
316	      severity: 'critical',
317	      reason: `${details.hoursAwake} hours awake`,
318	    });
319	  } else if (details.hoursAwake > 16) {
320	    addContribution(contributions, {
321	      id: 'fatigue',
322	      factor: 'Fatigue',
323	      points: 3,
324	      severity: 'caution',
325	      reason: `${details.hoursAwake} hours awake`,
326	    });
327	  } else if (details.hoursAwake > 12) {
328	    addContribution(contributions, {
329	      id: 'fatigue',
330	      factor: 'Fatigue',
331	      points: 1,
332	      severity: 'watch',
333	      reason: `${details.hoursAwake} hours awake`,
334	    });
335	  }
336	
337	  if (details.sleepHours < 4) {
338	    addContribution(contributions, {
339	      id: 'fatigue',
340	      factor: 'Fatigue',
341	      points: 6,
342	      severity: 'critical',
343	      reason: `${details.sleepHours} hours sleep in the last 24 hours`,
344	    });
345	  } else if (details.sleepHours < 6) {
346	    addContribution(contributions, {
347	      id: 'fatigue',
348	      factor: 'Fatigue',
349	      points: 3,
350	      severity: 'caution',
351	      reason: `${details.sleepHours} hours sleep in the last 24 hours`,
352	    });
353	  } else if (details.sleepHours < 7) {
354	    addContribution(contributions, {
355	      id: 'fatigue',
356	      factor: 'Fatigue',
357	      points: 1,
358	      severity: 'watch',
359	      reason: `${details.sleepHours} hours sleep in the last 24 hours`,
360	    });
361	  }
362	
363	  if (details.timeZonesCrossed >= 4) {
364	    addContribution(contributions, {
365	      id: 'fatigue',
366	      factor: 'Fatigue',
367	      points: 3,
