381	  const emotionScore = getDispatchEmotionScore(details);
382	  if (emotionScore >= 9) {
383	    addContribution(contributions, {
384	      id: 'eating',
385	      factor: 'Emotion / Eating',
386	      points: 10,
387	      severity: 'critical',
388	      reason: `Emotion score ${emotionScore.toFixed(1)} is a STOP condition`,
389	      hardStop: true,
