391	  } else if (emotionScore >= 7) {
392	    addContribution(contributions, {
393	      id: 'eating',
394	      factor: 'Emotion / Eating',
395	      points: 8,
396	      severity: 'critical',
397	      reason: `Emotion score ${emotionScore.toFixed(1)} indicates significant distraction risk`,
398	    });
399	  } else if (emotionScore >= 4) {
400	    addContribution(contributions, {
401	      id: 'eating',
402	      factor: 'Emotion / Eating',
403	      points: 5,
404	      severity: 'caution',
405	      reason: `Emotion score ${emotionScore.toFixed(1)} indicates distraction risk`,
406	    });
407	  } else if (emotionScore >= 2) {
408	    addContribution(contributions, {
409	      id: 'eating',
410	      factor: 'Emotion / Eating',
411	      points: 2,
412	      severity: 'watch',
413	      reason: `Emotion score ${emotionScore.toFixed(1)} is mildly elevated`,
414	    });
415	  }
416	
417	  if (details.totalFlightHours < 75) {
418	    addContribution(contributions, {
419	      id: 'currency',
420	      factor: 'Currency & Proficiency',
421	      points: 5,
422	      severity: 'caution',
423	      reason: `${details.totalFlightHours} total flight hours`,
424	    });
425	  } else if (details.totalFlightHours < 100) {
426	    addContribution(contributions, {
427	      id: 'currency',
428	      factor: 'Currency & Proficiency',
429	      points: 3,
430	      severity: 'watch',
431	      reason: `${details.totalFlightHours} total flight hours`,
432	    });
433	  } else if (details.totalFlightHours < 200) {
434	    addContribution(contributions, {
435	      id: 'currency',
436	      factor: 'Currency & Proficiency',
437	      points: 1,
438	      severity: 'watch',
439	      reason: `${details.totalFlightHours} total flight hours`,
440	    });
441	  }
442	
443	  if (details.hoursInType < 10) {
444	    addContribution(contributions, {
445	      id: 'currency',
446	      factor: 'Currency & Proficiency',
447	      points: 4,
448	      severity: 'caution',
449	      reason: `${details.hoursInType} total hours in type`,
450	    });
451	  } else if (details.hoursInType < 25) {
452	    addContribution(contributions, {
453	      id: 'currency',
454	      factor: 'Currency & Proficiency',
455	      points: 2,
456	      severity: 'watch',
457	      reason: `${details.hoursInType} total hours in type`,
458	    });
459	  }
460	
461	  if (details.hoursInType90 < 5) {
462	    addContribution(contributions, {
463	      id: 'currency',
464	      factor: 'Currency & Proficiency',
465	      points: 4,
466	      severity: 'caution',
467	      reason: `${details.hoursInType90} hours in type in the last 90 days`,
468	    });
469	  } else if (details.hoursInType90 < 10) {
470	    addContribution(contributions, {
471	      id: 'currency',
472	      factor: 'Currency & Proficiency',
473	      points: 2,
474	      severity: 'watch',
475	      reason: `${details.hoursInType90} hours in type in the last 90 days`,
476	    });
477	  }
478	
479	  const missingCurrency: Array<[boolean, string, boolean]> = [
480	    [
481	      details.daytimeLandingCurrent,
482	      'Daytime landing currency not confirmed',
483	      false,
484	    ],
485	    [
486	      details.nighttimeLandingCurrent,
487	      'Nighttime landing currency not confirmed',
488	      false,
489	    ],
490	    [details.medicalValid, 'Medical certificate not valid', true],
491	    [details.ifrCurrent, 'IFR currency not confirmed', false],
492	    [details.flightReviewCurrent, 'Flight review not current', true],
493	  ];
494	  for (const [isCurrent, reason, hardStop] of missingCurrency) {
495	    if (isCurrent) continue;
496	    addContribution(contributions, {
497	      id: 'currency',
498	      factor: 'Currency & Proficiency',
499	      points: hardStop ? 10 : 4,
500	      severity: hardStop ? 'critical' : 'caution',
501	      reason,
502	      hardStop,
503	    });
504	  }
505	
506	  const hardStops = contributions
507	    .filter((item) => item.hardStop)
508	    .map((item) => item.reason);
509	  const uncappedScore = Math.round(
510	    contributions.reduce((sum, item) => sum + item.points, 0),
511	  );
512	  const score = Math.min(MAX_IMSAFE_SCORE, uncappedScore);
513	  const readiness =
514	    hardStops.length > 0 ? 'no_go' : score >= 8 ? 'review' : 'ready';
515	
516	  return {
517	    score,
518	    uncappedScore,
519	    maxScore: MAX_IMSAFE_SCORE,
520	    readiness,
521	    currencyReady: isDispatchCurrencyReady(details),
522	    hardStops,
523	    contributions,
524	    checks: deriveDispatchImsafeChecks(details),
525	  };
526	}
