1	// Pure helper for normalizing the runway/heading text input on the
2	// pre-flight dispatch performance step.
3	//
4	// In US aviation, runway designators are 1–2 digits (the heading divided by
5	// 10, e.g. runway 22 ≈ 220°, runway 04 ≈ 040°). Headings are conventionally
6	// written as 3 digits with a leading zero where needed, e.g. "036" for 36°.
7	//
8	// Input rules:
9	//   - 1–2 digit input (any leading zeros) is a runway number → heading × 10
10	//   - 3 digit input (any leading zeros) is an explicit heading → as-is
11	//   - Anything else (non-numeric, blank, out of range) → null
12	//
13	// This matches what pilots enter on the form: "22" / "04" for a runway, "220"
14	// / "036" / "360" for an explicit heading.
15	
16	const NUMERIC_INPUT_RE = /^\s*([0-9]{1,3})\s*$/;
17	
18	export function normalizeRunwayHeading(input: string): number | null {
19	  if (!input) return null;
20	  const match = NUMERIC_INPUT_RE.exec(input);
21	  if (!match) return null;
22	  const digits = match[1];
23	  const numeric = Number.parseInt(digits, 10);
24	  if (!Number.isFinite(numeric)) return null;
25	
26	  if (digits.length <= 2) {
27	    // Runway number — must be 1..36
28	    if (numeric < 1 || numeric > 36) return null;
29	    return numeric * 10;
30	  }
31	
32	  // 3-digit explicit heading — must be 1..360 (we accept "360" but normalize
33	  // it; "000" is rejected because heading 0 is written as 360).
34	  if (numeric < 1 || numeric > 360) return null;
35	  return numeric;
36	}
