48	const BUCKET = (process.env.AWS_S3_BUCKET_NAME ?? '').trim();
49	const PRESIGN_EXPIRES_IN = 900; // 15 minutes
50	const MAX_PDF_BYTES = 25 * 1024 * 1024; // 25 MB
