52	const s3 = new S3Client({
53	  region: process.env.AWS_REGION?.trim() || 'us-east-1',
54	  credentials:
55	    process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY
