70	const presignSchema = z.object({
71	  locationId: z.string().uuid(),
72	  fileName: z.string().min(1).max(255),
73	  fileType: z.literal('application/pdf'),
74	  fileSize: z.number().int().positive().max(MAX_PDF_BYTES),
