77	// POST — presigned PUT URL for a ForeFlight PDF, namespaced to the location.
78	dispatchImport.post('/dispatch-import/presign', requireAuth(), async (c) => {
79	  if (!BUCKET) return bucketNotConfigured(c);
80	  const parsed = presignSchema.safeParse(await c.req.json().catch(() => ({})));
81	  if (!parsed.success) {
82	    return c.json(
83	      { error: `Invalid request: ${parsed.error.issues[0]?.message}` },
84	      400,
85	    );
86	  }
87	  const { locationId, fileName, fileType } = parsed.data;
88	
89	  const authUser = c.get('authUser') as AuthUser;
90	  const location = await verifyLocationAccess(locationId, authUser);
91	  if (!location) {
92	    return c.json({ error: 'Location not found or access denied' }, 403);
93	  }
94	
95	  const docId = randomUUID();
96	  const storagePath = `dispatch-imports/${locationId}/${docId}.pdf`;
97	  const uploadUrl = await getSignedUrl(
98	    s3,
99	    new PutObjectCommand({
100	      Bucket: BUCKET,
101	      Key: storagePath,
102	      ContentType: fileType,
103	      Metadata: { originalName: fileName },
104	    }),
105	    { expiresIn: PRESIGN_EXPIRES_IN },
106	  );
107	
108	  return c.json({ uploadUrl, docId, storagePath });
109	});
