116	// POST — enqueue an async ForeFlight extraction job (G5). Validates + pins the
117	// upload, creates a dispatch_import_job row, sends the Inngest event, and
118	// returns { jobId }. The client polls GET /dispatch-import/status/:jobId.
119	dispatchImport.post('/dispatch-import/extract', requireAuth(), async (c) => {
120	  if (!BUCKET) return bucketNotConfigured(c);
121	  const parsed = extractSchema.safeParse(await c.req.json().catch(() => ({})));
122	  if (!parsed.success) {
123	    return c.json(
124	      { error: `Invalid request: ${parsed.error.issues[0]?.message}` },
125	      400,
126	    );
127	  }
128	  const { locationId, storagePath } = parsed.data;
129	
130	  const authUser = c.get('authUser') as AuthUser;
131	  const location = await verifyLocationAccess(locationId, authUser);
132	  if (!location) {
133	    return c.json({ error: 'Location not found or access denied' }, 403);
134	  }
135	
136	  // Cross-tenant firewall: the object must live in this location's namespace,
137	  // so a caller cannot hand us another tenant's key to read.
138	  if (!storagePath.startsWith(`dispatch-imports/${locationId}/`)) {
139	    return c.json({ error: 'storagePath does not match location' }, 400);
140	  }
141	
142	  // Validate the actual uploaded object before enqueueing — a presigned PUT
143	  // does not prove the bytes are a PDF or within the size limit. Fail fast here
144	  // so the client gets an immediate, specific error instead of a failed job.
145	  let head: { ContentLength?: number; ContentType?: string };
146	  try {
147	    head = await s3.send(
148	      new HeadObjectCommand({ Bucket: BUCKET, Key: storagePath }),
149	    );
150	  } catch {
151	    return c.json({ error: 'Uploaded file not found' }, 404);
152	  }
153	  if ((head.ContentLength ?? 0) > MAX_PDF_BYTES) {
154	    return c.json({ error: 'Uploaded file exceeds the 25 MB limit' }, 413);
155	  }
156	  // Require an explicit application/pdf content type — a missing/other type is
157	  // rejected rather than trusted.
158	  if (head.ContentType !== 'application/pdf') {
159	    return c.json({ error: 'Uploaded file is not a PDF' }, 415);
160	  }
161	
162	  // Create the job row (scoped to the verified tenant) then fan out to Inngest.
163	  let jobId: string;
164	  try {
165	    const [job] = await db
166	      .insert(dispatchImportJob)
167	      .values({
168	        flightSchoolId: location.flightSchoolId,
169	        status: 'queued',
170	        progress: 0,
171	      })
172	      .returning({ id: dispatchImportJob.id });
173	    if (!job) {
174	      return c.json({ error: 'Failed to create extraction job' }, 500);
175	    }
176	    jobId = job.id;
177	  } catch (err) {
178	    console.error(
179	      '[dispatch-import] job insert failed:',
180	      safeErrorMessage(err),
181	    );
182	    return c.json({ error: 'Failed to create extraction job' }, 500);
183	  }
184	
185	  try {
186	    await inngest.send({
187	      name: 'dispatch-import/extract.requested',
188	      data: {
189	        jobId,
190	        locationId,
191	        storagePath,
192	        flightSchoolId: location.flightSchoolId,
193	      },
194	    });
195	  } catch (err) {
196	    // The event never landed — mark the job failed so the client's poll sees a
197	    // real failure rather than a job stuck in `queued` forever.
198	    console.error(
199	      '[dispatch-import] inngest send failed:',
200	      safeErrorMessage(err),
201	    );
202	    await db
203	      .update(dispatchImportJob)
204	      .set({
205	        status: 'failed',
206	        progress: 1,
207	        reason: 'document_extraction_failed',
208	        updatedAt: new Date(),
209	      })
210	      .where(
211	        and(
212	          eq(dispatchImportJob.id, jobId),
213	          eq(dispatchImportJob.flightSchoolId, location.flightSchoolId),
214	        ),
215	      );
216	    return c.json({ error: 'Failed to queue extraction' }, 502);
217	  }
218	
219	  return c.json({ jobId }, 202);
220	});
