222	const STATUS_VALUES = ['queued', 'extracting', 'complete', 'failed'] as const;
223	type DispatchJobStatus = (typeof STATUS_VALUES)[number];
224	
225	function normalizeStatus(value: string): DispatchJobStatus {
226	  return (STATUS_VALUES as readonly string[]).includes(value)
227	    ? (value as DispatchJobStatus)
228	    : 'failed';
229	}
230	
231	// GET — poll a dispatch extraction job. Scoped by the caller's resolved
232	// flight_school_id; a job belonging to another tenant 404s (never leaks).
233	dispatchImport.get(
234	  '/dispatch-import/status/:jobId',
235	  requireAuth(),
236	  async (c) => {
237	    const jobId = c.req.param('jobId');
238	    if (!jobId) return c.json({ error: 'jobId is required' }, 400);
239	
240	    const authUser = c.get('authUser') as AuthUser;
241	    const orgId = await resolveOrgIdFromSession(authUser, c);
242	    if (!orgId) {
243	      return c.json({ error: 'Could not resolve organization' }, 403);
244	    }
245	
246	    const [job] = await db
247	      .select({
248	        id: dispatchImportJob.id,
249	        status: dispatchImportJob.status,
250	        progress: dispatchImportJob.progress,
251	        reason: dispatchImportJob.reason,
252	        plan: dispatchImportJob.plan,
253	      })
254	      .from(dispatchImportJob)
255	      .where(
256	        and(
257	          eq(dispatchImportJob.id, jobId),
258	          eq(dispatchImportJob.flightSchoolId, orgId),
259	        ),
260	      )
261	      .limit(1);
262	
263	    if (!job) return c.json({ error: 'Job not found' }, 404);
264	
265	    const status = normalizeStatus(job.status);
266	    const body: {
267	      jobId: string;
268	      status: DispatchJobStatus;
269	      progress: number;
270	      reason?: string;
271	      plan?: ExtractedForeFlightPlan;
272	    } = {
273	      jobId: job.id,
274	      status,
275	      progress: typeof job.progress === 'number' ? job.progress : 0,
276	    };
277	    if (status === 'failed' && job.reason) {
278	      body.reason = job.reason;
279	    }
280	    if (status === 'complete' && job.plan) {
281	      body.plan = job.plan as ExtractedForeFlightPlan;
282	    }
283	    return c.json(body);
284	  },
285	);
