71	/**
72	 * Mark a curriculum import job as failed with an explicit error message so
73	 * `GET /import/status/:jobId` surfaces the real cause to the polling modal.
74	 * Safe to call from any catch site; failures here are logged but do not
75	 * re-throw because the caller is already in an error-handling path.
76	 */
77	type MarkEnrichmentFailedOptions = {
78	  jobId: string;
79	  orgId: string;
80	  error: string;
81	  expectedStatuses?: Array<'manifest_complete' | 'enriching'>;
82	  expectedCompletedBatches?: number;
83	};
84	
85	async function markEnrichmentFailed({
86	  jobId,
87	  orgId,
88	  error,
89	  expectedStatuses,
90	  expectedCompletedBatches,
91	}: MarkEnrichmentFailedOptions): Promise<boolean> {
92	  try {
93	    const predicates = [
94	      eq(curriculumImportJobs.id, jobId),
95	      eq(curriculumImportJobs.flightSchoolId, orgId),
96	    ];
97	    if (expectedStatuses && expectedStatuses.length > 0) {
98	      predicates.push(inArray(curriculumImportJobs.status, expectedStatuses));
99	    }
100	    if (typeof expectedCompletedBatches === 'number') {
101	      predicates.push(
102	        eq(curriculumImportJobs.completedBatches, expectedCompletedBatches),
103	      );
104	    }
105	
106	    const updated = await db
107	      .update(curriculumImportJobs)
108	      .set({ status: 'failed', error })
109	      .where(and(...predicates))
110	      .returning({ id: curriculumImportJobs.id });
111	
112	    return updated.length > 0;
113	  } catch (updateErr) {
114	    console.error(
115	      `[import-curriculum] Failed to mark job ${jobId} as failed (school ${orgId}):`,
116	      safeErrorMessage(updateErr),
117	    );
118	    return false;
119	  }
120	}
