127	// ─── Basic name normalization fallback ─────────────────────────────────────
128	function basicNormalizeName(raw: string): string {
129	  if (!raw || !raw.trim()) return raw;
130	  let name = raw.trim();
131	
132	  if (name.includes(',')) {
133	    const parts = name.split(',').map((s) => s.trim());
134	    if (parts.length === 2 && parts[0] && parts[1]) {
135	      name = `${parts[1]} ${parts[0]}`;
136	    }
137	  }
138	
139	  name = name
140	    .toLowerCase()
141	    .replace(/\b\w/g, (c) => c.toUpperCase())
142	    .replace(/\b(Ii|Iii|Iv)\b/g, (m) => m.toUpperCase())
143	    .replace(/\b(Jr|Sr)\b/g, (m) => `${m}.`)
144	    .replace(/\bMc(\w)/g, (_, c) => `Mc${c.toUpperCase()}`)
145	    .replace(/\bO'(\w)/g, (_, c) => `O'${c.toUpperCase()}`);
146	
147	  name = name.replace(/\s+/g, ' ').trim();
148	  return name;
149	}
