2	/**
3	 * KV → DB Backfill: loc_dispatch:* → flight_dispatches
4	 *
5	 * Reads every `loc_dispatch:{locationId}:{id}` entry from the `kv_store` table
6	 * and upserts it into the `flight_dispatches` Postgres table.
7	 *
8	 * The KV entries contain denormalised data (student/instructor names, tail
9	 * numbers) so FK columns (studentId, instructorId, aircraftId) are left NULL.
10	 * The original KV key is stored as a JSON prefix in the `notes` field so the
11	 * PUT route can find and sync the DB row when a status update arrives.
12	 *
13	 * Usage:
14	 *   tsx scripts/backfill-kv-dispatches.ts            # full run
15	 *   tsx scripts/backfill-kv-dispatches.ts --dry-run  # counts only
16	 *
17	 * Environment:
18	 *   DATABASE_URL — hilo-figma-atos Neon connection string (from .env)
19	 */
20	
21	import * as dotenv from 'dotenv';
22	dotenv.config();
23	
24	import { neon } from '@neondatabase/serverless';
25	import { and, eq, like } from 'drizzle-orm';
26	import { drizzle } from 'drizzle-orm/neon-http';
27	import * as schema from '../src/lib/schema';
28	
29	const args = process.argv.slice(2);
30	const isDryRun = args.includes('--dry-run');
31	
32	const TARGET_URL = process.env.DATABASE_URL;
33	if (!TARGET_URL) {
34	  console.error('❌ DATABASE_URL not set');
35	  process.exit(1);
36	}
37	
38	// Strip channel_binding — Neon preview URLs put it as the first query param;
39	// naive passthrough malforms the endpoint URL and every query fails as a 500.
40	const _targetUrl = new URL(TARGET_URL);
41	_targetUrl.searchParams.delete('channel_binding');
42	const targetSql = neon(_targetUrl.toString());
43	const db = drizzle(targetSql, { schema });
44	
45	const KV_PREFIX = 'loc_dispatch:';
46	
47	/** Prefix stored in notes so the PUT route can find the row by KV key. */
48	const KV_KEY_PREFIX = '[kv_key:';
49	
50	function toInt(v: unknown): number | null {
51	  if (v === null || v === undefined || v === '') return null;
52	  const n = Number(v);
53	  return Number.isFinite(n) ? Math.round(n) : null;
54	}
55	
56	function toTs(v: unknown): Date | null {
57	  if (!v) return null;
58	  const d = new Date(v as string);
59	  return Number.isNaN(d.getTime()) ? null : d;
60	}
61	
62	async function main(): Promise<void> {
63	  console.log(
64	    `\n=== KV → DB Dispatch Backfill${isDryRun ? ' (DRY RUN)' : ''} ===\n`,
65	  );
66	
67	  // 1. Load all loc_dispatch:* KV entries with their keys
68	  const kvRows = await db
69	    .select({ key: schema.kvStore.key, value: schema.kvStore.value })
70	    .from(schema.kvStore)
71	    .where(like(schema.kvStore.key, `${KV_PREFIX}%`));
72	
73	  console.log(`Found ${kvRows.length} KV dispatch entries.`);
74	  if (kvRows.length === 0) {
75	    console.log('Nothing to migrate.');
76	    return;
77	  }
78	
79	  // 2. Build a locationId → flightSchoolId map
80	  const locationRows = await db
81	    .select({
82	      id: schema.locations.id,
83	      flightSchoolId: schema.locations.flightSchoolId,
84	    })
85	    .from(schema.locations);
86	  const locationSchoolMap = new Map(
87	    locationRows.map((l) => [l.id, l.flightSchoolId]),
88	  );
89	
90	  let inserted = 0;
91	  let skipped = 0;
92	  let errors = 0;
93	
94	  for (const row of kvRows) {
95	    // Key format: loc_dispatch:{locationId}:{dispatchId}
96	    const withoutPrefix = row.key.slice(KV_PREFIX.length);
97	    const colonIdx = withoutPrefix.indexOf(':');
98	    if (colonIdx === -1) {
99	      console.warn(`  Skipping malformed key: ${row.key}`);
100	      skipped++;
101	      continue;
102	    }
103	
104	    const locationId = withoutPrefix.slice(0, colonIdx);
105	    const kvId = withoutPrefix.slice(colonIdx + 1);
106	    const flightSchoolId = locationSchoolMap.get(locationId);
107	
108	    if (!flightSchoolId) {
109	      console.warn(
110	        `  Skipping ${row.key}: locationId "${locationId}" not found in locations table`,
111	      );
112	      skipped++;
113	      continue;
114	    }
115	
116	    if (isDryRun) {
117	      console.log(`  [dry-run] Would insert dispatch from key: ${row.key}`);
118	      inserted++;
119	      continue;
120	    }
121	
122	    const d = (row.value ?? {}) as Record<string, unknown>;
123	
124	    // Embed the original KV key in notes so the PUT route can sync back.
125	    const kvTag = `${KV_KEY_PREFIX}${row.key}]`;
126	    const existingNotes = (d.notes as string) || '';
127	    const notes = existingNotes.includes(KV_KEY_PREFIX)
128	      ? existingNotes
129	      : [kvTag, existingNotes].filter(Boolean).join(' ').trim();
130	
131	    try {
132	      // Check if this KV key was already backfilled (notes contains the tag)
133	      const alreadyMigrated = await db
134	        .select({ id: schema.flightDispatches.id })
135	        .from(schema.flightDispatches)
136	        .where(
137	          and(
138	            eq(schema.flightDispatches.locationId, locationId),
139	            like(schema.flightDispatches.notes, `%${kvTag}%`),
140	          ),
141	        )
142	        .limit(1);
143	
144	      if (alreadyMigrated.length > 0) {
145	        skipped++;
146	        continue;
147	      }
148	
149	      await db.insert(schema.flightDispatches).values({
150	        flightSchoolId,
151	        locationId,
152	        type: (d.type as string) || null,
153	        status: (d.status as string) || 'pending',
154	        route: (d.route as string) || null,
155	        departure: (d.departure as string) || null,
156	        arrival: (d.arrival as string) || null,
157	        riskScore: toInt(d.riskScore),
158	        riskLevel: (d.riskLevel as string) || null,
159	        pave: (d.pave as schema.NewFlightDispatch['pave']) ?? null,
160	        weather: (d.weather as schema.NewFlightDispatch['weather']) ?? null,
161	        weightBalance:
162	          (d.weightBalance as schema.NewFlightDispatch['weightBalance']) ??
163	          null,
164	        notes,
165	        submittedAt: toTs(d.submittedAt ?? d.createdAt) ?? undefined,
166	        approvedAt: toTs(d.approvedAt),
167	      });
168	
169	      inserted++;
170	      console.log(`  ✓ ${kvId} (location: ${locationId})`);
171	    } catch (err: unknown) {
172	      const msg = err instanceof Error ? err.message : String(err);
173	      console.error(`  ✗ ${row.key}: ${msg}`);
174	      errors++;
175	    }
176	  }
177	
178	  console.log(
179	    `\nDone. inserted=${inserted}  skipped=${skipped}  errors=${errors}`,
180	  );
181	  if (isDryRun) {
182	    console.log('(Dry run — no rows were written.)');
183	  }
184	}
185	
186	main().catch((err) => {
187	  console.error('Fatal:', err);
188	  process.exit(1);
189	});
