56	const UPLOAD_TIMEOUT_MS = 120_000; // S3 PUT of up to a 25 MB PDF
57	
58	/** fetch with an AbortController timeout so a hung presign/upload/extract/
59	 * submit surfaces an actionable error instead of spinning forever. */
60	async function fetchWithTimeout(
61	  url: string,
62	  init: RequestInit = {},
63	  timeoutMs = REQUEST_TIMEOUT_MS,
64	): Promise<Response> {
65	  const controller = new AbortController();
66	  const timer = setTimeout(() => controller.abort(), timeoutMs);
67	  try {
68	    return await fetch(url, { ...init, signal: controller.signal });
69	  } catch (err) {
70	    if (err instanceof DOMException && err.name === 'AbortError') {
71	      throw new Error('The request timed out — please try again.');
72	    }
73	    throw err;
74	  } finally {
75	    clearTimeout(timer);
76	  }
77	}
