79	type Phase = 'upload' | 'extracting' | 'ready' | 'submitting' | 'done';
80	
81	interface PresignResponse {
82	  uploadUrl: string;
83	  docId: string;
84	  storagePath: string;
85	}
86	/** Async extract is fire-and-poll: POST returns a jobId (202); the plan
87	 * arrives later via DispatchImportProgress polling the status endpoint. */
88	interface ExtractResponse {
89	  jobId: string;
90	}
91	interface DispatchResponse {
92	  dispatch?: { riskScore?: number; riskLevel?: string };
93	}
94	
95	/** Shown for `duration` when the plan carried a non-positive (0/missing) en-
96	 * route time. Never render a misleading "0 hr". */
97	const DURATION_NOT_IN_PDF = 'Not in PDF';
98	
99	/**
100	 * Map the AI-resolved plan onto a DispatchDraft AND record, per field, whether
101	 * the value came from the ForeFlight plan or fell back to a system default.
102	 *
103	 * Contract (FROZEN): a field is `'foreflight'` only when it was populated from
104	 * a NON-NULL field of the extended ExtractedForeFlightPlan; otherwise it is
105	 * `'default'` (came from `buildDraft(null)`). When `plan` is null every field
106	 * is `'default'`.
107	 */
108	export function draftFromPlan(plan: ExtractedForeFlightPlan | null): {
109	  draft: DispatchDraft;
110	  provenance: DispatchProvenance;
111	} {
112	  const base = buildDraft(null);
113	
114	  const scheduledDate = plan?.scheduledDate ?? base.scheduledDate;
115	  const scheduledTime = plan?.scheduledTime ?? base.scheduledTime;
116	  const departure = (plan?.departure ?? base.departure).toUpperCase();
117	  const destination = (plan?.destination ?? base.destination).toUpperCase();
118	
119	  // Honest duration: a real positive value renders as hours; a 0/null en-route
120	  // time is NOT rendered as "0 hr" — surface an explicit "not in PDF" instead.
121	  const hasRealDuration = plan?.durationHours != null && plan.durationHours > 0;
122	  const duration = hasRealDuration
123	    ? `${plan?.durationHours} hr`
124	    : plan?.durationHours === 0
125	      ? DURATION_NOT_IN_PDF
126	      : base.duration;
127	
128	  const draft: DispatchDraft = {
129	    ...base,
130	    profileName: 'ForeFlight import',
131	    student: 'ForeFlight import',
132	    aircraft: plan?.aircraft ?? base.aircraft,
133	    route: plan?.route ?? base.route,
134	    departure,
135	    destination,
136	    scheduledDate,
137	    scheduledTime,
138	    duration,
139	    departurePerformance: airportPerformanceFromPayload(
140	      base.performance,
141	      'departure',
142	      departure,
143	      scheduledDate,
144	      scheduledTime,
145	    ),
146	    destinationPerformance: airportPerformanceFromPayload(
147	      base.performance,
148	      'destination',
149	      destination,
150	      scheduledDate,
151	      scheduledTime,
152	    ),
153	    riskFactors: {
154	      ...base.riskFactors,
155	      notes: plan?.notes ?? base.riskFactors.notes,
156	    },
157	  };
158	
159	  // `'foreflight'` iff the source plan field was non-null (and, for duration,
160	  // a real positive value — a 0 falls back to the "not in PDF" default).
161	  const origin = (fromPlan: boolean): 'foreflight' | 'default' =>
162	    fromPlan ? 'foreflight' : 'default';
163	  const provenance: DispatchProvenance = {
164	    aircraft: origin(plan?.aircraft != null),
165	    route: origin(plan?.route != null),
166	    departure: origin(plan?.departure != null),
167	    destination: origin(plan?.destination != null),
168	    scheduledDate: origin(plan?.scheduledDate != null),
169	    scheduledTime: origin(plan?.scheduledTime != null),
170	    duration: origin(hasRealDuration),
171	  };
172	
173	  return { draft, provenance };
174	}
