292	function parseInspectionDateInput(raw: string | null | undefined): Date | null {
293	  if (!raw) return null;
294	  const trimmed = raw.trim();
295	  if (!trimmed) return null;
296	  const ymd = /^(\d{4})-(\d{2})-(\d{2})$/.exec(trimmed);
297	  if (ymd) {
298	    const d = new Date(`${ymd[1]}-${ymd[2]}-${ymd[3]}T00:00:00`);
299	    return Number.isNaN(d.getTime()) ? null : d;
300	  }
301	  const parsed = new Date(trimmed);
302	  if (Number.isNaN(parsed.getTime())) return null;
303	  parsed.setHours(0, 0, 0, 0);
304	  return parsed;
305	}
