308	  raw: string | null | undefined,
309	  now: Date = new Date(),
310	): boolean {
311	  const dueDate = parseInspectionDateInput(raw);
312	  if (!dueDate) return false;
313	  const today = new Date(now);
314	  today.setHours(0, 0, 0, 0);
315	  return dueDate >= today;
316	}
