348	export function deriveInspectionDueDatesFromMaintenance(params: {
349	  maintenanceData: unknown;
350	  equipmentData: unknown;
351	}): {
352	  annualDueDate: string | null;
353	  transponderDueDate: string | null;
354	  pitotStaticDueDate: string | null;
355	  eltDueDate: string | null;
356	} {
357	  const eqRecord = isRecord(params.equipmentData) ? params.equipmentData : null;
358	  const records = toMaintenanceInspectionRecords(params.maintenanceData);
359	  const activeInspectionRecords = records.filter((record) => {
360	    const status =
361	      typeof record.status === 'string' ? record.status.toLowerCase() : '';
362	    return !NON_CURRENT_MAINTENANCE_STATUSES.has(status);
363	  });
364	
365	  const findInspectionRecord = (...patterns: string[]) =>
366	    activeInspectionRecords.find((record) => {
367	      const name = normalizeInspectionName(record);
368	      return patterns.some((pattern) => name.includes(pattern));
369	    });
370	
371	  const annualRec = findInspectionRecord('annual inspection');
372	  const standaloneTransponderRec = activeInspectionRecords.find((record) => {
373	    const name = normalizeInspectionName(record);
374	    return (
375	      (name.includes('transponder inspection') ||
376	        name.includes('transponder check')) &&
377	      !name.includes('altimeter')
378	    );
379	  });
380	  const combinedAltimeterTransponderRec = activeInspectionRecords.find(
381	    (record) => {
382	      const name = normalizeInspectionName(record);
383	      return name.includes('altimeter') && name.includes('transponder');
384	    },
385	  );
386	  const transponderRec =
387	    standaloneTransponderRec ?? combinedAltimeterTransponderRec;
388	  const pitotStaticRec = findInspectionRecord(
389	    'pitot-static inspection',
390	    'pitot static inspection',
391	    'pitot-static check',
392	    'pitot static check',
393	  );
394	  const eltRec = findInspectionRecord('elt inspection', 'elt check');
395	
396	  const annualDueDate =
397	    readInspectionDueDateFromRecord(annualRec) ??
398	    normalizeInspectionDueDate(eqRecord?.nextAnnual);
399	  const transponderDueDate = readInspectionDueDateFromRecord(transponderRec);
400	  const pitotStaticDueDate =
401	    readInspectionDueDateFromRecord(pitotStaticRec) ??
402	    readInspectionDueDateFromRecord(combinedAltimeterTransponderRec);
403	  const eltDueDate = readInspectionDueDateFromRecord(eltRec);
404	
405	  return {
406	    annualDueDate,
407	    transponderDueDate,
408	    pitotStaticDueDate,
409	    eltDueDate,
410	  };
