421	/**
422	 * Parse the schedule view's free-form `estimatedDuration` into minutes so the
423	 * Performance step can derive a default arrival time from a flight's
424	 * scheduled start. Accepts the formats currently produced by the schedule
425	 * service: `"1h"`, `"1h 30m"`, `"30m"`, `"90min"`, `"1.5"` (decimal hours),
426	 * `"1:30"` (HH:MM), or any string that starts with a number we treat as
427	 * hours. Returns 0 when the input can't be parsed.
428	 */
429	export function parseDurationToMinutes(
430	  input: string | null | undefined,
431	): number {
432	  if (!input) return 0;
433	  const s = String(input).trim().toLowerCase();
434	  if (!s) return 0;
435	  // HH:MM
436	  const colon = s.match(/^(\d+):(\d{1,2})$/);
437	  if (colon) {
438	    return Number.parseInt(colon[1]) * 60 + Number.parseInt(colon[2]);
439	  }
440	  // "Xh Ym" / "Xh" / "Ym" / "Ymin"
441	  const hoursMatch = s.match(/(\d+(?:\.\d+)?)\s*h(?:rs?|ours?)?/);
442	  const minutesMatch = s.match(/(\d+(?:\.\d+)?)\s*m(?:ins?|inutes?)?/);
443	  if (hoursMatch || minutesMatch) {
444	    const h = hoursMatch ? Number.parseFloat(hoursMatch[1]) : 0;
445	    const m = minutesMatch ? Number.parseFloat(minutesMatch[1]) : 0;
446	    return Math.round(h * 60 + m);
447	  }
448	  // Bare number → hours
449	  const bare = Number.parseFloat(s);
450	  if (!Number.isNaN(bare) && bare > 0) {
451	    return Math.round(bare * 60);
452	  }
453	  return 0;
454	}
