635	export interface DeriveAirworthinessReasonsInput {
636	  hundredHourData: {
637	    dueAtHours: number | null;
638	    currentHours: number | null;
639	  } | null;
640	  inspectionDates: Record<string, string>;
641	  dateInspectionNaIds?: readonly string[];
642	  /** Override "today" for deterministic tests. Defaults to new Date(). */
643	  now?: Date;
644	}
645	
646	export function deriveAirworthinessReasons(
647	  input: DeriveAirworthinessReasonsInput,
648	): AirworthinessReason[] {
649	  const reasons: AirworthinessReason[] = [];
650	
651	  const now = input.now ?? new Date();
652	  const today = new Date(now);
653	  today.setHours(0, 0, 0, 0);
654	  const soonThreshold = new Date(today);
655	  soonThreshold.setDate(soonThreshold.getDate() + 30);
656	
657	  const hData = input.hundredHourData;
658	  if (hData && hData.dueAtHours != null && hData.currentHours != null) {
659	    const remaining = hData.dueAtHours - hData.currentHours;
660	    if (remaining <= 0) {
661	      reasons.push({
662	        code: 'hundred_hour_overdue',
663	        severity: 'grounded',
664	        message: `100-hour inspection overdue by ${Math.abs(remaining).toFixed(1)} hrs`,
665	        source: 'maintenance',
666	        itemId: '100hr-inspection',
667	      });
668	    } else if (remaining <= 5) {
669	      reasons.push({
670	        code: 'hundred_hour_due_soon',
671	        severity: 'caution',
672	        message: `100-hour inspection due in ${remaining.toFixed(1)} hrs`,
673	        source: 'maintenance',
674	        itemId: '100hr-inspection',
675	      });
676	    }
677	  }
678	
679	  const dateInspectionNaIds = new Set(input.dateInspectionNaIds ?? []);
680	  for (const id of DATE_INSPECTION_IDS) {
681	    if (dateInspectionNaIds.has(id)) continue;
682	    const raw = input.inspectionDates[id];
683	    if (!raw) continue;
684	    const dueDate = parseInspectionDateInput(raw);
685	    if (!dueDate) continue;
686	    const label = INSPECTION_LABELS[id] ?? id;
687	    const codeBase = id.replace(/-/g, '_');
688	    if (dueDate < today) {
689	      reasons.push({
690	        code: `${codeBase}_overdue`,
691	        severity: 'grounded',
692	        message: `${label} expired on ${formatInspectionDate(dueDate)}`,
693	        source: 'inspection',
694	        itemId: id,
695	      });
696	    } else if (dueDate <= soonThreshold) {
697	      const days = daysFromTo(today, dueDate);
698	      const dayWord = days === 1 ? 'day' : 'days';
699	      reasons.push({
700	        code: `${codeBase}_due_soon`,
701	        severity: 'caution',
702	        message: `${label} due in ${days} ${dayWord} (${formatInspectionDate(dueDate)})`,
703	        source: 'inspection',
704	        itemId: id,
705	      });
706	    }
707	  }
708	
709	  // Stable severity ordering: grounded reasons first, caution second; within a
710	  // severity, preserve insertion order so the UI summary picks a deterministic
711	  // representative reason (the first 100-hour rule, then date inspections in
712	  // DATE_INSPECTION_IDS order).
713	  reasons.sort((a, b) => {
714	    if (a.severity === b.severity) return 0;
715	    return a.severity === 'grounded' ? -1 : 1;
716	  });
717	
718	  return reasons;
719	}
