774	export function buildStudentDispatchRiskResult({
775	  departurePerf,
776	  destinationPerf,
777	  imsafeChecks,
778	  imsafeDetails,
779	  airworthinessChecks,
780	  safetyChecks,
781	  paveNotes,
782	}: BuildStudentDispatchRiskResultInput): DispatchRiskResult {
783	  const worstDensityAlt = getWorstDensityAltitude(
784	    departurePerf,
785	    destinationPerf,
786	  );
787	  const notFitImsafeItems = IMSAFE_ITEMS.filter(
788	    (item) => imsafeChecks[item.id] === IMSAFE_READINESS.notFit,
789	  );
790	  const granularImsafeScore = imsafeDetails
791	    ? scoreDispatchImsafe(imsafeDetails)
792	    : null;
793	  const incompleteAirworthinessIds =
794	    listIncompleteAirworthinessIds(airworthinessChecks);
795	  const uncheckedSafetyItems = ADDITIONAL_SAFETY_ITEMS.filter(
796	    (item) => !safetyChecks[item.id],
797	  );
798	  const paveScores = {
799	    pilot: clampPaveCategoryScore(
800	      granularImsafeScore
801	        ? granularImsafeScore.score
802	        : notFitImsafeItems.length * STUDENT_DISPATCH_PAVE_SCORING.imsafeNotFit,
803	    ),
804	    aircraft: clampPaveCategoryScore(
805	      incompleteAirworthinessIds.length *
806	        STUDENT_DISPATCH_PAVE_SCORING.missingAirworthiness,
807	    ),
808	    environment:
809	      worstDensityAlt > STUDENT_DISPATCH_PAVE_SCORING.densityAltitudeCautionFeet
810	        ? STUDENT_DISPATCH_PAVE_SCORING.highDensityAltitude
811	        : STUDENT_DISPATCH_PAVE_SCORING.normalDensityAltitude,
812	    external: clampPaveCategoryScore(
813	      uncheckedSafetyItems.length *
814	        STUDENT_DISPATCH_PAVE_SCORING.uncheckedSafetyItem,
815	    ),
816	  };
817	  const riskScore = Math.min(
818	    100,
819	    paveScores.pilot +
820	      paveScores.aircraft +
821	      paveScores.environment +
822	      paveScores.external,
823	  );
824	  const riskLevel = deriveDispatchRiskLevel(riskScore);
825	
826	  return {
827	    riskScore,
828	    riskLevel,
829	    pave: [
830	      {
831	        label: 'Pilot',
832	        score: paveScores.pilot,
833	        max: PAVE_CATEGORY_MAX_SCORE,
834	        items: granularImsafeScore
835	          ? granularImsafeScore.contributions.map(
836	              (item) => `${item.factor}: ${item.reason}`,
837	            )
838	          : notFitImsafeItems.map((item) => item.id),
839	      },
840	      {
841	        label: 'Aircraft',
842	        score: paveScores.aircraft,
843	        max: PAVE_CATEGORY_MAX_SCORE,
844	        items: incompleteAirworthinessIds,
845	      },
846	      {
847	        label: 'Environment',
848	        score: paveScores.environment,
849	        max: PAVE_CATEGORY_MAX_SCORE,
850	        items: [
851	          `Dep ${departurePerf.identifier || '—'} DA: ${departurePerf.densityAltitude || '—'}ft`,
852	          `Dest ${destinationPerf.identifier || '—'} DA: ${destinationPerf.densityAltitude || '—'}ft`,
853	          `Dep wind: ${departurePerf.windDirection || '—'}° at ${departurePerf.windSpeed || '—'}kt`,
854	        ],
855	      },
856	      {
857	        label: 'External',
858	        score: paveScores.external,
859	        max: PAVE_CATEGORY_MAX_SCORE,
860	        items: uncheckedSafetyItems.map((item) => item.id),
861	      },
862	    ],
863	    paveNotes,
864	  };
865	}
