941	export function getIncompleteAirworthinessItems(params: {
942	  checks: Record<string, AirworthinessStatus | boolean | undefined>;
943	  items?: readonly AirworthinessItem[];
944	  hundredHourData: {
945	    dueAtHours: number | null;
946	    currentHours: number | null;
947	  } | null;
948	  loadingHundredHour?: boolean;
949	  inspectionDates?: Record<string, string>;
950	  dateInspectionNaIds?: readonly string[];
951	  now?: Date;
952	}): AirworthinessResolutionItem[] {
953	  const {
954	    checks,
955	    items = AIRWORTHINESS_ITEMS,
956	    hundredHourData,
957	    loadingHundredHour = false,
958	    inspectionDates = {},
959	    dateInspectionNaIds = [],
960	    now = new Date(),
961	  } = params;
962	  const today = new Date(now);
963	  today.setHours(0, 0, 0, 0);
964	  const naIds = new Set(dateInspectionNaIds);
965	  const out: AirworthinessResolutionItem[] = [];
966	
967	  for (const item of items) {
968	    if (item.id === '100hr-inspection') {
969	      if (isAirworthinessItemComplete(checks, item.id)) continue;
970	      const hasSystemValues =
971	        hundredHourData?.dueAtHours != null &&
972	        hundredHourData?.currentHours != null;
973	      out.push({
974	        id: item.id,
975	        label: item.label,
976	        description: item.description,
977	        requiredBy: hasSystemValues ? 'System' : 'Instructor',
978	        completionMethod: hasSystemValues
979	          ? 'System validation'
980	          : 'Instructor approval',
981	        currentStatus: loadingHundredHour
982	          ? 'pending'
983	          : hasSystemValues &&
984	              hundredHourData.currentHours! >= hundredHourData.dueAtHours!
985	            ? 'failed'
986	            : 'missing',
987	        primaryAction: hasSystemValues
988	          ? 'Request instructor review'
989	          : 'Validate',
990	        allowNa: false,
991	      });
992	      continue;
993	    }
994	
995	    if (DATE_INSPECTION_IDS.includes(item.id as DateInspectionId)) {
996	      const isNa = checks[item.id] === 'na' || naIds.has(item.id);
997	      if (isNa) continue;
998	      const rawDueDate = inspectionDates[item.id];
999	      const dueDate = parseInspectionDateInput(rawDueDate);
1000	      const isCurrent = dueDate ? dueDate >= today : false;
1001	      if (isCurrent && isAirworthinessItemComplete(checks, item.id)) continue;
1002	
1003	      out.push({
1004	        id: item.id,
1005	        label: item.label,
1006	        description: item.description,
1007	        requiredBy: dueDate ? 'System' : 'Student',
1008	        completionMethod: dueDate ? 'System validation' : 'Document upload',
1009	        currentStatus: dueDate && dueDate < today ? 'failed' : 'missing',
1010	        primaryAction:
1011	          dueDate && dueDate < today ? 'Request instructor review' : 'Validate',
1012	        allowNa: item.allowsNa === true,
1013	      });
1014	      continue;
1015	    }
1016	
1017	    if (isAirworthinessItemComplete(checks, item.id)) continue;
1018	    if (item.category === 'ADs' || item.category === 'Maintenance') {
1019	      out.push({
1020	        id: item.id,
1021	        label: item.label,
1022	        description: item.description,
1023	        requiredBy: 'Instructor',
