1206	export function buildDispatchRiskReview(params: {
1207	  airworthinessChecks: Record<string, AirworthinessStatus>;
1208	  imsafeChecks: Record<string, ImsafeReadinessAnswer>;
1209	  imsafeDetails?: DispatchImsafeDetails;

1210	  safetyChecks: Record<string, boolean>;
1211	  departurePerf: AirportPerformanceType;
1212	  destinationPerf: AirportPerformanceType;
1213	  wbCompute: WBComputeSnapshot | null;
1214	  paveNotes: Record<'pilot' | 'aircraft' | 'environment' | 'external', string>;
1215	}): DispatchRiskReview {
1216	  const {
1217	    airworthinessChecks,
1218	    imsafeChecks,
1219	    imsafeDetails,
1220	    safetyChecks,
1221	    departurePerf,
1222	    destinationPerf,
1223	    wbCompute,
1224	    paveNotes,
1225	  } = params;
1226	
1227	  const additiveMissing = ADDITIONAL_SAFETY_ITEMS.filter(
1228	    (item) => !safetyChecks[item.id],
1229	  );
1230	  const additiveDrivers = additiveMissing.map((item) => item.label);
1231	  const additiveScore = Math.min(100, additiveMissing.length * 12);
1232	
1233	  const crewNoItems = IMSAFE_ITEMS.filter(
1234	    (item) => imsafeChecks[item.id] !== 'yes',
1235	  );
1236	  const granularImsafeScore = imsafeDetails
1237	    ? scoreDispatchImsafe(imsafeDetails)
1238	    : null;
1239	  const crewDrivers = granularImsafeScore
1240	    ? granularImsafeScore.contributions.map(
1241	        (item) => `${item.factor}: ${item.reason}`,
1242	      )
1243	    : crewNoItems.map((item) => item.label);
1244	  const crewScore = granularImsafeScore
1245	    ? granularImsafeScore.readiness === 'no_go'
1246	      ? 100
1247	      : Math.min(100, granularImsafeScore.score * 4)
1248	    : Math.min(100, crewNoItems.length * 15);
1249	
1250	  const incompleteAirworthiness = AIRWORTHINESS_ITEMS.filter(
1251	    (item) => !isAirworthinessItemComplete(airworthinessChecks, item.id),
1252	  );
1253	  const taskDrivers = [
1254	    ...incompleteAirworthiness.slice(0, 3).map((item) => item.label),
1255	  ];
1256	  if (!departurePerf.groundRoll || !destinationPerf.groundRoll) {
1257	    taskDrivers.push('Performance planning incomplete');
1258	  }
1259	  if (!wbCompute || wbCompute.status === 'danger' || wbCompute.gtwWeight <= 0) {
1260	    taskDrivers.push('Weight & Balance not dispatch-ready');
1261	  } else if (wbCompute.status === 'warning') {
1262	    taskDrivers.push('Weight & Balance approaching limits');
1263	  }
1264	  const taskScore = Math.min(
1265	    100,
1266	    incompleteAirworthiness.length * 8 +
1267	      (!departurePerf.groundRoll || !destinationPerf.groundRoll ? 18 : 0) +
1268	      (!wbCompute || wbCompute.gtwWeight <= 0
1269	        ? 25
1270	        : wbCompute.status === 'danger'
1271	          ? 45
1272	          : wbCompute.status === 'warning'
1273	            ? 18
1274	            : 0),
1275	  );
1276	
1277	  const categories: DispatchRiskCategoryReview[] = [
1278	    {
1279	      id: 'additive',
1280	      label: 'Additive Conditions',
1281	      score: additiveScore,
1282	      classification: classifyRiskScore(additiveScore),
1283	      drivers: additiveDrivers,
1284	    },
1285	    {
1286	      id: 'crew',
1287	      label: 'Crew Factors',
1288	      score: crewScore,
1289	      classification: classifyRiskScore(crewScore),
1290	      drivers: crewDrivers,
1291	    },
1292	    {
1293	      id: 'task',
1294	      label: 'Task Loading',
1295	      score: taskScore,
1296	      classification: classifyRiskScore(taskScore),
1297	      drivers: taskDrivers,
1298	    },
1299	  ];
1300	
1301	  const scores0To10 = categories.map((category) => category.score / 10);
1302	  const severeCount = scores0To10.filter((score) => score >= 7).length;
1303	  const highCount = scores0To10.filter((score) => score >= 6).length;
1304	  const moderateCount = scores0To10.filter((score) => score >= 4).length;
1305	  const interaction =
1306	    severeCount === 3
1307	      ? { tier: 'Extreme Triple Overlap', amplification: 30 }
1308	      : highCount === 3
1309	        ? { tier: 'Triple Overlap', amplification: 25 }
1310	        : severeCount >= 2
1311	          ? { tier: 'Severe Double Overlap', amplification: 20 }
1312	          : highCount >= 2
1313	            ? { tier: 'High Double Overlap', amplification: 15 }
1314	            : moderateCount >= 2
1315	              ? { tier: 'Moderate Overlap', amplification: 5 }
1316	              : { tier: 'No significant overlap', amplification: 0 };
1317	  const baseScore = additiveScore * 0.4 + crewScore * 0.35 + taskScore * 0.25;
1318	  const mitigationCredit = Math.min(
1319	    10,
1320	    Object.values(paveNotes).filter((note) => note.trim().length > 0).length *
1321	      2,
1322	  );
1323	  const calculatedFinalScore = Math.max(
1324	    0,
1325	    Math.min(
1326	      100,
1327	      Math.round(baseScore + interaction.amplification - mitigationCredit),
1328	    ),
1329	  );
1330	  const finalScore =
1331	    granularImsafeScore?.readiness === 'no_go'
1332	      ? Math.max(76, calculatedFinalScore)
1333	      : calculatedFinalScore;
1334	  const classification = classifyRiskScore(finalScore);
1335	  const compoundFlags: string[] = [];
1336	  if (!safetyChecks['weather-briefing'] && imsafeChecks.fatigue !== 'yes') {
1337	    compoundFlags.push('Fatigue + weather');
1338	  }
1339	  if (wbCompute?.status === 'danger' && !safetyChecks['personal-minimums']) {
1340	    compoundFlags.push('Missing W&B + marginal performance');
1341	  }
1342	  if (!safetyChecks.notams && !safetyChecks.tfrs) {
1343	    compoundFlags.push('Airspace constraints not fully reviewed');
1344	  }
1345	
1346	  return {
1347	    score: finalScore,
1348	    classification,
1349	    recommendation:
1350	      classification === 'GREEN'
1351	        ? 'GO'
1352	        : classification === 'YELLOW'
1353	          ? 'CONDITIONAL_GO'
1354	          : 'NO_GO',
1355	    instructorReviewRequired: classification !== 'GREEN',
1356	    categories,
1357	    calculation: {
1358	      summary:
1359	        'The review starts with three category scores, weights them by their role in dispatch risk, then applies overlap and mitigation adjustments before classifying the final score.',
1360	      baseScore,
1361	      finalScore,
1362	      formulaLabel:
1363	        'Weighted category score + interaction amplification - mitigation credit = final dispatch risk score',
1364	      factors: [
1365	        {
1366	          label: 'Additive Conditions',
1367	          rawScore: additiveScore,
1368	          weightedScore: additiveScore * 0.4,
1369	          weightLabel: '40%',
1370	          maxScore: 100,
1371	          drivers: additiveDrivers,
1372	          detail:
1373	            'Safety planning items such as NOTAMs, TFRs, weather briefing, flight plan, personal minimums, and emergency equipment.',
1374	        },
1375	        {
1376	          label: 'Crew Factors',
1377	          rawScore: crewScore,
1378	          weightedScore: crewScore * 0.35,
1379	          weightLabel: '35%',
1380	          maxScore: 100,
1381	          drivers: crewDrivers,
1382	          detail: 'IMSAFE readiness items marked not fit or not confirmed.',
1383	        },
1384	        {
1385	          label: 'Task Loading',
1386	          rawScore: taskScore,
1387	          weightedScore: taskScore * 0.25,
1388	          weightLabel: '25%',
1389	          maxScore: 100,
1390	          drivers: taskDrivers,
1391	          detail:
1392	            'Aircraft readiness, performance planning, and Weight & Balance readiness.',
1393	        },
1394	      ],
1395	      adjustments: [
1396	        {
1397	          label: 'Interaction amplification',
1398	          points: interaction.amplification,
1399	          explanation:
1400	            interaction.amplification > 0
1401	              ? `${interaction.tier}: multiple elevated categories increase combined dispatch risk.`
1402	              : 'No material overlap was detected across the major risk categories.',
1403	        },
1404	        {
1405	          label: 'Mitigation credit',
1406	          points: -mitigationCredit,
1407	          explanation:
1408	            mitigationCredit > 0
1409	              ? 'Documented mitigation notes reduce the score so the review reflects controls already identified for instructor review.'
1410	              : 'No mitigation notes were documented, so no mitigation credit was applied.',
1411	        },
1412	      ],
1413	      thresholds: STUDENT_RISK_REVIEW_THRESHOLDS,
1414	    },
1415	    interaction: {
1416	      ...interaction,
1417	      explanation:
1418	        interaction.amplification > 0
1419	          ? 'Multiple risk categories are elevated together.'
1420	          : 'No significant broad category overlap was detected.',
1421	    },
1422	    compoundFlags,
1423	    mitigations: Object.values(paveNotes).some((note) => note.trim())
1424	      ? ['Student documented mitigation notes for review.']
1425	      : [],
1426	  };
1427	}
