const hydrateForecastWind = useCallback(
  async (
    role: 'departure' | 'destination',
    rawIcao: string,
    scheduledLocal: string,
  ) => {
    const setter =
      role === 'departure' ? setDeparturePerf : setDestinationPerf;
    const icao = rawIcao.trim().toUpperCase();
    if (!icao || !scheduledLocal) {
      setter((prev) =>
        prev.forecastStatus === 'idle' &&
        prev.forecastValidFrom === '' &&
        prev.forecastValidTo === ''
          ? prev
          : {
              ...prev,
              forecastStatus: 'idle',
              forecastError: '',
              forecastValidFrom: '',
              forecastValidTo: '',
            },
      );
      return;
    }
    setter((prev) => ({
      ...prev,
      forecastStatus: 'loading',
      forecastError: '',
    }));
    try {
      const res = await fetch(
        `${API_BASE}/weather/taf?ids=${encodeURIComponent(icao)}`,
        { credentials: 'include', headers: getServerApiHeaders() },
      );
      const body = (await res.json().catch(() => ({}))) as TafFetchPayload;
      if (!res.ok) {
        throw new Error(
          body.error || `TAF fetch failed (HTTP ${res.status})`,
        );
      }
      const periods = body.tafPeriods ?? [];
      const matched = selectTafPeriodForLocalTime(periods, scheduledLocal);
      setter((prev) => {
        if (!matched) {
          return {
            ...prev,
            forecastStatus: 'success',
            forecastError: '',
            forecastValidFrom: '',
            forecastValidTo: '',
            // Clear a stale TAF wind source so the badge falls back to
            // METAR/manual; do NOT overwrite the wind values themselves —
            // METAR (or the user's manual edit) stays in place.
            windSource: prev.windSource === 'taf' ? 'metar' : prev.windSource,
          };
        }
        // Manual edits win — show the matched period in the badge so the
        // student sees what the forecast says, but don't overwrite their
        // typed wind direction/speed.
        if (prev.windSource === 'manual') {
          return {
            ...prev,
            forecastStatus: 'success',
            forecastError: '',
            forecastValidFrom: matched.validFrom ?? '',
            forecastValidTo: matched.validTo ?? '',
          };
        }
        const wDir = matched.wind?.direction;
        const wSpd = matched.wind?.speed;
        return {
          ...prev,
          forecastStatus: 'success',
          forecastError: '',
          forecastValidFrom: matched.validFrom ?? '',
          forecastValidTo: matched.validTo ?? '',
          windDirection:
            wDir !== undefined ? String(wDir) : prev.windDirection,
          windSpeed: wSpd !== undefined ? String(wSpd) : prev.windSpeed,
          windSource: 'taf',
        };
      });
    } catch (err) {
      const msg = safeErrorMessage(err);
      setter((prev) => ({
        ...prev,
        forecastStatus: 'error',
        forecastError: msg,
      }));
    }
  },
  [],
);

